{
  "name": "Medicare Savings Programs (QMB, SLMB, QI)",
  "eligibility": {
    "age": null,
    "income_limits": {
      "notes": "Virginia’s Medicare Savings Programs are for people with Medicare Part A; age is not the deciding factor. QMB has the lowest income limit and the broadest coverage, SLMB is higher, and QI is highest and subject to federal funding availability.",
      "household_table": [
        {
          "household_size": 1,
          "QMB": 1325,
          "SLMB": 1585,
          "QI": 1781
        },
        {
          "household_size": 2,
          "QMB": 1783,
          "SLMB": 2135,
          "QI": 2400
        }
      ],
      "income_definition": "Income includes Social Security, pensions, wages, interest, dividends, and other earned and unearned income. The income of both spouses is counted."
    },
    "asset_limits": {
      "resource_limits": {
        "individual": 8400,
        "couple": 12600
      },
      "what_counts": [
        "Bank accounts",
        "Cash",
        "Stocks, bonds, and similar financial resources",
        "Other countable resources used by Medicaid eligibility rules"
      ],
      "what_is_exempt": [
        "The home the person lives in, if treated as a primary residence under Medicaid rules",
        "One vehicle, in many Medicaid eligibility situations",
        "Other resources that Virginia Medicaid excludes under its broader Medicaid rules"
      ],
      "notes": "The source materials show a resource limit for MSP applicants in Virginia and indicate that eligibility is based on income and resources within specific limits."
    },
    "other_requirements": [
      "Must have Medicare Part A",
      "Must meet Virginia Medicaid residency rules",
      "QMB, SLMB, and QI are for people who are not enrolled in full Medicaid but need help with Medicare costs",
      "QI is limited to available federal funds and is typically first-come, first-served"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": {
      "QMB": "Pays Medicare Part A premiums, Medicare Part B premiums, deductibles, coinsurance, and copayments for Medicare-covered services.",
      "SLMB": "Pays the monthly Medicare Part B premium only.",
      "QI": "Pays the monthly Medicare Part B premium only, while funding is available."
    },
    "varies_by": "priority_tier"
  },
  "application": {
    "methods": [
      "Online: https://www.commonhelp.virginia.gov",
      "Phone: Cover Virginia Call Center at 1-855-242-8282",
      "Phone TDD: 1-888-221-1590",
      "In person: local Virginia Department of Social Services office",
      "Mail: Cardinal Care Correspondence Center, P.O. Box 1820, Richmond, VA 23218"
    ],
    "processing_time": "No single statewide processing-time number was identified in the source materials; MSP applications can be submitted at any time and are processed through Virginia Medicaid eligibility systems.",
    "waitlist": "No waitlist is described for QMB or SLMB. QI is limited by available federal funding and can function like a funding-based cutoff rather than a traditional waitlist.",
    "forms": [
      "Application for Health Coverage & Financial Assistance",
      "Virginia Medicaid / CommonHelp online application"
    ],
    "documents": [
      "Proof of Medicare Part A enrollment",
      "Social Security award letter or other income proof",
      "Pension statements",
      "Recent bank statements",
      "Proof of resources if requested",
      "Proof of Virginia residency",
      "Identification information for the applicant and spouse",
      "Citizenship or immigration documents if requested by the agency"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide in Virginia; administered through Virginia Medicaid and local Department of Social Services offices.",
    "regional_variations": "Benefit rules are statewide and uniform. The main variation is administrative: local DSS offices can differ in how quickly they schedule interviews or process paperwork, but the program itself does not have county-specific benefit levels.",
    "offices_or_providers": [
      "Virginia Department of Social Services local offices",
      "Cover Virginia / Virginia Medicaid"
    ]
  },
  "official_source": "https://www.dmas.virginia.gov/for-members/benefits-and-services/other-programs-and-guidelines/",
  "gotchas": [
    "QMB is the most valuable tier because it covers Medicare cost sharing, but many families only look for premium help and miss the deductibles and copays.",
    "QI is not guaranteed the same way QMB and SLMB are; it depends on available funding.",
    "The spouse’s income is counted, which surprises many couples.",
    "Even if someone has income above QMB, they may still qualify for SLMB or QI.",
    "People often confuse MSPs with full Medicaid; these programs mainly help with Medicare costs rather than replacing Medicare.",
    "Applications can be filed anytime, so families should not wait for an open enrollment period."
  ],
  "data_shape_notes": "This program has a tiered structure: eligibility gets looser from QMB to SLMB to QI, while benefits get narrower. Income and resource limits matter, and spouse income is counted."
}
